  const invoice = {
    lines: [{ qty: 2, unitPrice: 980, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1960);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 1960);
});

test('invoiceTotals with multiple lines', () => {
