    lines: [
      { qty: 2, unitPrice: 980, vatRate: 0 },
      { qty: 1, unitPrice: 8500, vatRate: 0 },
      { qty: 3, unitPrice: 50, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1960 + 8500 + 150);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 1960 + 8500 + 150);
});

test('invoiceTotals with empty lines array', () => {
